PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, display_name TEXT NOT NULL, locale TEXT NOT NULL DEFAULT 'en', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS providers(id TEXT PRIMARY KEY, kind TEXT NOT NULL, label TEXT NOT NULL, base_url TEXT, enabled INTEGER NOT NULL DEFAULT 0, active_model TEXT, config_json TEXT NOT NULL DEFAULT '{}', last_health_json TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS models(id TEXT PRIMARY KEY, provider_id TEXT NOT NULL REFERENCES providers(id) ON DELETE CASCADE, name TEXT NOT NULL, capabilities_json TEXT NOT NULL, context_length INTEGER, local INTEGER NOT NULL DEFAULT 0, size_bytes INTEGER, last_seen_at TEXT NOT NULL, UNIQUE(provider_id,name));
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY, title TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, role TEXT NOT NULL, content TEXT NOT NULL, provider_id TEXT, model TEXT, created_at TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS memories(id TEXT PRIMARY KEY, layer TEXT NOT NULL, content TEXT NOT NULL, source TEXT NOT NULL, sensitivity TEXT NOT NULL, approved INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, expires_at TEXT, metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS memory_embeddings(memory_id TEXT NOT NULL REFERENCES memories(id) ON DELETE CASCADE, provider_id TEXT NOT NULL, model TEXT NOT NULL, vector_json TEXT NOT NULL, dimensions INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(memory_id,provider_id,model));
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY, path TEXT NOT NULL UNIQUE, content_hash TEXT, mime_type TEXT, size_bytes INTEGER NOT NULL, modified_at TEXT NOT NULL, indexed_at TEXT, metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS document_chunks(id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE, ordinal INTEGER NOT NULL, text TEXT NOT NULL, embedding_json TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', UNIQUE(document_id,ordinal));
CREATE TABLE IF NOT EXISTS agents(id TEXT PRIMARY KEY, name TEXT NOT NULL, definition_json TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS agent_runs(id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id), task_id TEXT, parent_run_id TEXT, state TEXT NOT NULL, input_json TEXT NOT NULL, output_json TEXT, error TEXT, started_at TEXT NOT NULL, completed_at TEXT);
CREATE TABLE IF NOT EXISTS tools(name TEXT PRIMARY KEY, definition_json TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tool_runs(id TEXT PRIMARY KEY, tool_name TEXT NOT NULL REFERENCES tools(name), task_id TEXT, agent_run_id TEXT, risk TEXT NOT NULL, input_redacted_json TEXT NOT NULL, output_redacted_json TEXT, state TEXT NOT NULL, verification_json TEXT, started_at TEXT NOT NULL, completed_at TEXT);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY, title TEXT NOT NULL, request TEXT NOT NULL, status TEXT NOT NULL, plan_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, completed_at TEXT, error TEXT);
CREATE TABLE IF NOT EXISTS task_steps(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, agent_id TEXT, tool_name TEXT, ordinal INTEGER NOT NULL, depends_on_json TEXT NOT NULL DEFAULT '[]', state TEXT NOT NULL, input_json TEXT NOT NULL DEFAULT '{}', output_json TEXT, error TEXT, retry_count INTEGER NOT NULL DEFAULT 0, started_at TEXT, completed_at TEXT);
CREATE TABLE IF NOT EXISTS automations(id TEXT PRIMARY KEY, name TEXT NOT NULL, trigger_json TEXT NOT NULL, steps_json TEXT NOT NULL, permission_scope_json TEXT NOT NULL, risk TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, last_run_at TEXT, next_run_at TEXT);
CREATE TABLE IF NOT EXISTS automation_runs(id TEXT PRIMARY KEY, automation_id TEXT NOT NULL REFERENCES automations(id), trigger_json TEXT NOT NULL, actions_json TEXT NOT NULL, state TEXT NOT NULL, verification_json TEXT, errors_json TEXT NOT NULL DEFAULT '[]', started_at TEXT NOT NULL, completed_at TEXT);
CREATE TABLE IF NOT EXISTS permissions(id TEXT PRIMARY KEY, subject_type TEXT NOT NULL, subject_id TEXT NOT NULL, capability TEXT NOT NULL, scope_json TEXT NOT NULL, risk TEXT NOT NULL, granted INTEGER NOT NULL, expires_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approvals(id TEXT PRIMARY KEY, task_id TEXT NOT NULL, action TEXT NOT NULL, risk TEXT NOT NULL, summary TEXT NOT NULL, payload_json TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, resolved_at TEXT);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY, timestamp TEXT NOT NULL, category TEXT NOT NULL, action TEXT NOT NULL, actor TEXT NOT NULL, risk TEXT NOT NULL, status TEXT NOT NULL, summary TEXT NOT NULL, details_redacted_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS api_registry(api_id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, base_url TEXT NOT NULL, authentication TEXT NOT NULL, https INTEGER NOT NULL, cors TEXT NOT NULL, status TEXT NOT NULL, last_checked TEXT, rate_limit TEXT, documentation_url TEXT NOT NULL, adapter_name TEXT, capabilities_json TEXT NOT NULL DEFAULT '[]', enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS integrations(id TEXT PRIMARY KEY, kind TEXT NOT NULL, label TEXT NOT NULL, state TEXT NOT NULL, config_json TEXT NOT NULL DEFAULT '{}', last_checked TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, kind TEXT NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, read INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS system_snapshots(id TEXT PRIMARY KEY, measured_at TEXT NOT NULL, metrics_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS research_sources(id TEXT PRIMARY KEY, task_id TEXT NOT NULL, title TEXT NOT NULL, url TEXT NOT NULL, retrieved_at TEXT NOT NULL, key_finding TEXT NOT NULL, confidence REAL NOT NULL, content_hash TEXT, metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS knowledge_entities(id TEXT PRIMARY KEY, kind TEXT NOT NULL, label TEXT NOT NULL, source_url TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_relations(id TEXT PRIMARY KEY, from_entity_id TEXT NOT NULL REFERENCES knowledge_entities(id) ON DELETE CASCADE, to_entity_id TEXT NOT NULL REFERENCES knowledge_entities(id) ON DELETE CASCADE, relation TEXT NOT NULL, weight REAL NOT NULL DEFAULT 1.0, metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS plugins(id TEXT PRIMARY KEY, name TEXT NOT NULL, version TEXT NOT NULL, manifest_json TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, installed_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_messages_conversation_time ON messages(conversation_id,created_at);
CREATE INDEX IF NOT EXISTS idx_memories_layer_time ON memories(layer,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_documents_modified ON documents(modified_at DESC);
CREATE INDEX IF NOT EXISTS idx_agent_runs_task ON agent_runs(task_id,state);
CREATE INDEX IF NOT EXISTS idx_tool_runs_task ON tool_runs(task_id,state);
CREATE INDEX IF NOT EXISTS idx_tasks_status_time ON tasks(status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_task_steps_task_ordinal ON task_steps(task_id,ordinal);
CREATE INDEX IF NOT EXISTS idx_automation_due ON automations(enabled,next_run_at);
CREATE INDEX IF NOT EXISTS idx_audit_time_category ON audit_logs(timestamp DESC,category);
CREATE INDEX IF NOT EXISTS idx_research_task ON research_sources(task_id,retrieved_at);
INSERT OR IGNORE INTO schema_migrations(version,applied_at) VALUES(1,datetime('now'));
